<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/blog-storage.php';
require_once __DIR__ . '/includes/playnow-promos.php';
require_once __DIR__ . '/includes/admin-date.php';
require_auth();

if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && csrf_validate(is_string($_POST['csrf_token'] ?? null) ? $_POST['csrf_token'] : null)) {
    try {
        $code = trim((string) ($_POST['promo_code'] ?? ''));
        $newCode = trim((string) ($_POST['new_promo_code'] ?? ''));
        $customCode = trim((string) ($_POST['custom_promo_code'] ?? ''));
        $target = request_string('target_url', 500) ?? '';
        $title = request_string('og_title', 180) ?? '';
        $description = request_string('og_description', 300) ?? '';
        $image = request_string('og_image', 500) ?? '';
        if (strlen($code) > 64 || strlen($newCode) > 64 || strlen($customCode) > 64) throw new InvalidArgumentException('Promo code must be 8-64 characters using only letters, numbers, hyphens, or underscores.');
        if ($code !== '') {
            $_SESSION['promo_notice'] = playnow_promo_update($code, $target, $title, $description, $image, $newCode) ? 'Promo link updated.' : 'Promo link not found.';
        } else {
            $created = playnow_promo_create($target, $title, $description, $image, $customCode);
            $_SESSION['promo_notice'] = 'Promo link created: /promo-code/' . $created['code'];
        }
    } catch (Throwable $error) { $_SESSION['promo_notice'] = $error->getMessage(); }
    header('Location: /admin/playnow-promos.php'); exit;
}
$path = blog_storage_dir() . '/playnow-clicks.json';
$raw = is_readable($path) ? file_get_contents($path) : '';
$data = json_decode($raw ?: '', true);
$promos = is_array($data) && is_array($data['promos'] ?? null) ? $data['promos'] : [];
$notice = (string) ($_SESSION['promo_notice'] ?? ''); unset($_SESSION['promo_notice']);
?>
<!DOCTYPE html><html lang="en-PH"><head><meta name="robots" content="noindex,nofollow"><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Promo Links | Admin</title><link rel="stylesheet" href="/admin/style.css"><style>
.admin-container{max-width:1180px;margin:40px auto;padding:24px;background:var(--surface);border:1px solid var(--border-strong);border-radius:var(--radius-lg);box-shadow:var(--shadow)}.admin-header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:24px;padding-bottom:16px;border-bottom:2px solid var(--border)}.promo-form{max-width:680px}.promo-form input,.promo-form textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid var(--border);border-radius:6px;font:inherit}.promo-form textarea{min-height:72px;resize:vertical}.promo-form label{display:block;margin-top:10px;font-size:.82rem;font-weight:800}.promo-form button{margin-top:12px}.promo-image-preview{display:block;max-width:180px;max-height:100px;margin-top:8px;border:1px solid var(--border);border-radius:6px;object-fit:cover}.tracker-table{width:100%;border-collapse:collapse;margin-top:18px;background:#fff;border:1px solid var(--border);font-size:.84rem}.tracker-table th,.tracker-table td{border-bottom:1px solid var(--border);padding:9px;text-align:left;vertical-align:top}.tracker-table th{background:#fff8ea;color:var(--brand-dark)}.value-cell{overflow-wrap:anywhere}
</style></head><body><div class="page-shell"><?php require __DIR__ . '/partials/admin-header.php'; ?><main style="padding:20px 16px"><div class="admin-container"><div class="admin-header"><div><h1 style="font-size:1.6rem;color:var(--brand-dark)">Promo Links</h1><p style="font-size:.88rem;color:var(--text-muted)">Create and manage tracked promo links.</p></div><a href="/admin/playnow-tracker.php" class="btn btn-secondary btn-sm">Back to Tracker</a></div><?php if ($notice !== ''): ?><p class="notice ok"><?= h($notice) ?></p><?php endif; ?><section class="tracker-card"><h2 style="font-size:1.05rem;color:var(--brand-dark)">Generate promo link</h2><form method="post" class="promo-form"><?= csrf_input() ?><input type="hidden" name="promo_code" value=""><label>Custom promo code<input name="custom_promo_code" maxlength="64" placeholder="Optional, 8-64 URL-safe characters"></label><label>Destination URL<input name="target_url" value="/playnow" required maxlength="500"></label><label>OG Title<input name="og_title" maxlength="180" placeholder="Play Now"></label><label>OG Description<textarea name="og_description" maxlength="300"></textarea></label><label>OG Image<input class="promo-image-upload" type="file" accept="image/jpeg,image/png,image/webp"><input name="og_image" type="hidden" value=""><span class="promo-image-status" role="status"></span><img class="promo-image-preview" alt="OG image preview" hidden></label><button class="btn btn-primary btn-sm" type="submit">Generate promo link</button></form></section><table class="tracker-table"><thead><tr><th>Promo URL</th><th>Destination</th><th>Clicks</th><th>Last click</th><th>Edit</th></tr></thead><tbody><?php foreach ($promos as $promo): if (!is_array($promo)) continue; ?><tr><td class="value-cell"><a href="/promo-code/<?= h($promo['code'] ?? '') ?>?preview=1" target="_blank" rel="noopener">/promo-code/<?= h($promo['code'] ?? '') ?></a></td><td class="value-cell"><?= h($promo['targetUrl'] ?? '') ?></td><td><?= (int) ($promo['clicks'] ?? 0) ?></td><td><?= h(admin_format_date($promo['lastClickAt'] ?? '') ?: ($promo['lastClickAt'] ?? '')) ?></td><td><details><summary>Edit</summary><form method="post" class="promo-form"><?= csrf_input() ?><input type="hidden" name="promo_code" value="<?= h($promo['code'] ?? '') ?>"><label>Promo code<input name="new_promo_code" value="<?= h($promo['code'] ?? '') ?>" required maxlength="64"></label><label>Destination URL<input name="target_url" value="<?= h($promo['targetUrl'] ?? '/playnow') ?>" required maxlength="500"></label><label>OG Title<input name="og_title" value="<?= h($promo['ogTitle'] ?? '') ?>" maxlength="180"></label><label>OG Description<textarea name="og_description" maxlength="300"><?= h($promo['ogDescription'] ?? '') ?></textarea></label><label>OG Image<input class="promo-image-upload" type="file" accept="image/jpeg,image/png,image/webp"><input name="og_image" type="hidden" value="<?= h($promo['ogImage'] ?? '') ?>"><span class="promo-image-status" role="status"></span></label><button class="btn btn-secondary btn-sm" type="submit">Save</button></form></details></td></tr><?php endforeach; ?></tbody></table></div></main></div><script>document.querySelectorAll('.promo-image-upload').forEach((input)=>input.addEventListener('change',async()=>{const file=input.files?.[0],form=input.closest('form'),status=form?.querySelector('.promo-image-status'),hidden=form?.querySelector('input[name="og_image"]'),csrf=form?.querySelector('input[name="csrf_token"]');if(!file||!form||!status||!hidden||!csrf)return;status.textContent='Uploading image...';const body=new FormData();body.append('image',file);body.append('csrf_token',csrf.value);try{const response=await fetch('/admin/upload-image.php',{method:'POST',body,credentials:'same-origin'}),result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Image upload failed.');hidden.value=result.path;status.textContent='Image uploaded.'}catch(error){status.textContent=error.message}input.value='';}));</script></body></html>
